package services
import("context";"errors";"strings";"time";"github.com/ngwebwork/payflow/internal/models";"github.com/ngwebwork/payflow/internal/repositories";"go.mongodb.org/mongo-driver/bson/primitive";"go.mongodb.org/mongo-driver/mongo")
type SubscriptionInput struct{CustomerID string `json:"customerId"`;Plan string `json:"plan"`;Amount float64 `json:"amount"`;Currency string `json:"currency"`;BillingCycle string `json:"billingCycle"`;Status string `json:"status"`;NextPaymentDate string `json:"nextPaymentDate"`};type SubscriptionService struct{repo *repositories.SubscriptionRepository};func NewSubscriptionService(r *repositories.SubscriptionRepository)*SubscriptionService{return &SubscriptionService{r}}
func(s *SubscriptionService) make(c context.Context,u primitive.ObjectID,in SubscriptionInput,old *models.Subscription)(*models.Subscription,error){id,e:=primitive.ObjectIDFromHex(strings.TrimSpace(in.CustomerID));if e!=nil{return nil,errors.New("invalid customer id")};x,e:=s.repo.Customer(c,u,id);if e!=nil{return nil,e};if x==nil{return nil,mongo.ErrNoDocuments};if strings.TrimSpace(in.Plan)==""||in.Amount<=0{return nil,errors.New("plan and positive amount are required")};if in.BillingCycle!="monthly"&&in.BillingCycle!="quarterly"&&in.BillingCycle!="yearly"{return nil,errors.New("invalid billing cycle")};if in.Status==""{in.Status="active"};if in.Status!="active"&&in.Status!="paused"&&in.Status!="cancelled"&&in.Status!="expired"{return nil,errors.New("invalid status")};d,e:=time.Parse("2006-01-02",in.NextPaymentDate);if e!=nil{return nil,errors.New("invalid next payment date")};now:=time.Now().UTC();v:=&models.Subscription{ID:primitive.NewObjectID(),UserID:u,CustomerID:id,Plan:strings.TrimSpace(in.Plan),Amount:in.Amount,Currency:"NGN",BillingCycle:in.BillingCycle,Status:in.Status,NextPaymentDate:d.UTC(),CreatedAt:now,UpdatedAt:now};if old!=nil{v.ID=old.ID;v.CreatedAt=old.CreatedAt};return v,nil};func(s *SubscriptionService) Create(c context.Context,u primitive.ObjectID,in SubscriptionInput)(*models.Subscription,error){v,e:=s.make(c,u,in,nil);if e!=nil{return nil,e};return v,s.repo.Create(c,v)};func(s *SubscriptionService) Update(c context.Context,u,id primitive.ObjectID,in SubscriptionInput)(*models.Subscription,error){o,e:=s.repo.Get(c,u,id);if e!=nil||o==nil{return o,e};v,e:=s.make(c,u,in,o);if e!=nil{return nil,e};return v,s.repo.Update(c,u,id,v)};func(s *SubscriptionService) List(c context.Context,u primitive.ObjectID,q repositories.SubscriptionQuery)(repositories.SubscriptionPage,error){if q.Page<1{q.Page=1};if q.Limit<1||q.Limit>100{q.Limit=20};return s.repo.List(c,u,q)};func(s *SubscriptionService) Get(c context.Context,u,id primitive.ObjectID)(*models.Subscription,error){return s.repo.Get(c,u,id)};func(s *SubscriptionService) Cancel(c context.Context,u,id primitive.ObjectID)error{return s.repo.Cancel(c,u,id)};func(s *SubscriptionService) Summary(c context.Context,u primitive.ObjectID)(repositories.SubscriptionSummary,error){return s.repo.Summary(c,u)}
